114	template <int N, int num_warp_n, bool transpose> struct SelectCopy {
115	  static constexpr int remainder = (N / num_warp_n) % 16;
116	  using type = std::conditional_t<
117	      remainder == 4 || remainder == 8 || remainder == 0,
118	      std::conditional_t<
119	          transpose,
120	          std::conditional_t<
121	              remainder == 4, SM75_U32x1_LDSM_N,
122	              std::conditional_t<remainder == 8, SM75_U32x2_LDSM_N,
123	                                 SM75_U32x4_LDSM_N>>,
124	          std::conditional_t<
125	              remainder == 4, SM75_U16x2_LDSM_T,
126	              std::conditional_t<remainder == 8, SM75_U16x4_LDSM_T,
127	                                 SM75_U16x8_LDSM_T>>>,
128	      DefaultCopy>;
129	};
130	
131	template <int Bits, int N, int K, bool K_inner, int num_warp_n, int leading_dim,
132	          typename Enable = void>
133	struct OperandTraits {
134	  // Primary template, use padded layout and default copy
135	  static constexpr int stride = leading_dim;
136	  static constexpr int padded =
137	      stride % (256 / Bits) == 0 ? stride + 128 / Bits : stride;
138	  using Layout = typename std::conditional<
139	      K_inner, Layout<Shape<Int<N>, Int<leading_dim>>, Shape<Int<padded>, _1>>,
140	      Layout<Shape<Int<leading_dim>, Int<K>>, Shape<_1, Int<padded>>>>::type;
141	  using Copy = DefaultCopy;
142	};
143	
144	template <int N, int K, int num_warp_n, int leading_dim>
145	struct OperandTraits<16, N, K, true, num_warp_n, leading_dim,
146	                     typename std::enable_if<leading_dim % 64 == 32>::type> {
147	  using LayoutAtom = decltype(composition(
148	      Swizzle<2, 3, 3>{}, Layout<Shape<_8, _32>, Stride<_32, _1>>{}));
149	  using Layout =
150	      decltype(tile_to_shape(LayoutAtom{}, Shape<Int<N>, Int<leading_dim>>{}));
151	  using Copy = typename SelectCopy<N, num_warp_n, true>::type;
152	};
