264	template <int M, int N, int K, int num_warp_m, int num_warp_n, bool trans_A,
265	          bool trans_B, bool clear_accum, int lda, int ldb, int offset_a,
266	          int offset_b, typename A_type_raw, typename B_type_raw,
267	          typename C_type_raw>
268	class GemmTensorOp {
269	public:
270	  using A_type_cute = typename tl::to_cute_type<A_type_raw>::type;
271	  using B_type_cute = typename tl::to_cute_type<B_type_raw>::type;
272	  using A_type =
273	      typename std::conditional<std::is_same<A_type_cute, float>::value,
274	                                tfloat32_t, A_type_cute>::type;
275	  using B_type =
276	      typename std::conditional<std::is_same<B_type_cute, float>::value,
277	                                tfloat32_t, B_type_cute>::type;
278	  using C_type = C_type_raw;
279	
280	  using Instruction = DispatchInstruction<A_type_raw, B_type_raw, C_type_raw,
281	                                          num_warp_m, num_warp_n, N>;
282	
283	  using OperandATraits = OperandTraits<sizeof_bits<A_type>::value, M, K,
284	                                       !trans_A, num_warp_m, lda>;
285	  using OperandBTraits =
286	      OperandTraits<sizeof_bits<B_type>::value, N, K, trans_B, num_warp_n, ldb>;
287	
288	  using SmemLayoutA = typename OperandATraits::Layout;
289	  using SmemLayoutB = typename OperandBTraits::Layout;
290	  using SmemCopyA = Copy_Atom<typename OperandATraits::Copy, A_type>;
291	  using SmemCopyB = Copy_Atom<typename OperandBTraits::Copy, B_type>;
292	
293	  using TileMma = TiledMMA<typename Instruction::MMA,
294	                           Layout<Shape<Int<num_warp_m>, Int<num_warp_n>, _1>>,
295	                           typename Instruction::MMA_Group>;
296	
297	  template <class... Args>
298	  static CUTE_DEVICE auto remove_swizzle(Layout<Args...> const &layout) {
299	    return layout;
300	  }
301	  // In fp16, when layout is KxN and n_warp is 1 and N % 64 == 0
302	  // the original layout fail to compile, currently using this as a workaround
303	  template <class... Args>
304	  static CUTE_DEVICE auto
305	  remove_swizzle(ComposedLayout<Args...> const &layout) {
306	    if constexpr (sizeof(A_type) == 2)
307	      return layout.layout_b();
308	    else
309	      return layout;
310	  }
311	
312	  template <int offset, int NN, int KK, bool trans, int lddim, typename Engine0,
313	            typename Layout0>
314	  static CUTE_DEVICE auto get_region_tensor(Tensor<Engine0, Layout0> &sa) {
315	    if constexpr (offset == 0) {
316	      return composition(
317	          sa,
318	          Layout<Shape<Int<NN>, Int<KK>>,
319	                 Stride<_1, typename std::conditional<trans, Int<NN>,
320	                                                      Int<lddim>>::type>>{});
321	    } else {
322	      if constexpr (trans) {
323	        static_assert(offset % KK == 0, "Offset must be a multiple of K");
324	        constexpr int offset_n = offset / KK;
325	        return flat_divide(sa, Shape<Int<NN>, Int<KK>>{})(_, _, _0{},
326	                                                          Int<offset_n>{});
327	      } else {
328	        static_assert(offset % NN == 0, "Offset must be a multiple of N");
329	        constexpr int offset_n = offset / NN;
330	        return flat_divide(sa, Shape<Int<NN>, Int<KK>>{})(_, _, Int<offset_n>{},
331	                                                          _0{});
332	      }
333	    }
334	  }
335	
336	  static CUTE_DEVICE void body(A_type_raw *pA, B_type_raw *pB, C_type_raw *pC) {
337	    const int tid = threadIdx.x;
338	    Tensor sA_all = make_tensor(make_smem_ptr(reinterpret_cast<A_type *>(pA)),
339	                                SmemLayoutA{});
340	    Tensor sB_all = make_tensor(make_smem_ptr(reinterpret_cast<B_type *>(pB)),
341	                                SmemLayoutB{});
342	    Tensor sA = get_region_tensor<offset_a, M, K, !trans_A, lda>(sA_all);
343	    Tensor sB = get_region_tensor<offset_b, N, K, trans_B, ldb>(sB_all);
344	    TileMma tiled_mma;
345	    auto thr_mma = tiled_mma.get_thread_slice(tid);
346	    auto tiled_copy_A = make_tiled_copy_A(SmemCopyA{}, tiled_mma);
347	    auto tiled_copy_B = make_tiled_copy_B(SmemCopyB{}, tiled_mma);
348	    auto thr_copy_A = tiled_copy_A.get_thread_slice(tid);
349	    auto thr_copy_B = tiled_copy_B.get_thread_slice(tid);
350	
351	    Tensor tCrA = thr_mma.partition_fragment_A(sA);
352	    Tensor tCrB = thr_mma.partition_fragment_B(sB);
353	    Tensor tCsA = thr_copy_A.partition_S(sA);
354	    Tensor tCsB = thr_copy_B.partition_S(sB);
355	
356	    Tensor tCrA_copy_view = thr_copy_A.retile_D(tCrA);
357	    Tensor tCrB_copy_view = thr_copy_B.retile_D(tCrB);
358	
359	    Tensor acc =
360	        make_tensor(make_rmem_ptr(reinterpret_cast<C_type *>(pC)),
361	                    partition_shape_C(tiled_mma, Shape<Int<M>, Int<N>>{}));
362	
363	    // when layout is KxN and n_warp is 1, there seem to be a bug, use this as a
364	    // workaround
365	    auto tCrA_view = make_tensor(tCrA.data(), remove_swizzle(tCrA.layout()));
366	    auto tCrB_view = make_tensor(tCrB.data(), remove_swizzle(tCrB.layout()));
367	    if constexpr (clear_accum) {
368	      clear(acc);
369	    }
370	    CUTE_UNROLL
371	    for (int k = 0; k < size<2>(tCrA); ++k) {
372	      copy(tiled_copy_A, tCsA(_, _, k), tCrA_copy_view(_, _, k));
373	      copy(tiled_copy_B, tCsB(_, _, k), tCrB_copy_view(_, _, k));
374	      gemm(tiled_mma, tCrA_view(_, _, k), tCrB_view(_, _, k), acc);
375	    }
376	  }
377	
378	  static CUTE_DEVICE void body_rs(A_type_raw *pA, B_type_raw *pB,
379	                                  C_type_raw *pC) {
380	    const int tid = threadIdx.x;
381	    Tensor sB_all = make_tensor(make_smem_ptr(reinterpret_cast<B_type *>(pB)),
382	                                SmemLayoutB{});
383	    Tensor sB = get_region_tensor<offset_b, N, K, trans_B, ldb>(sB_all);
384	    TileMma tiled_mma;
385	    auto thr_mma = tiled_mma.get_thread_slice(tid);
386	    auto tiled_copy_B = make_tiled_copy_B(SmemCopyB{}, tiled_mma);
387	    auto thr_copy_B = tiled_copy_B.get_thread_slice(tid);
388	
389	    Tensor tCrB = thr_mma.partition_fragment_B(sB);
390	    Tensor tCsB = thr_copy_B.partition_S(sB);
391	
392	    Tensor tCrB_copy_view = thr_copy_B.retile_D(tCrB);
393	
394	    Tensor acc =
395	        make_tensor(make_rmem_ptr(reinterpret_cast<C_type *>(pC)),
396	                    partition_shape_C(tiled_mma, Shape<Int<M>, Int<N>>{}));
397	    Tensor tCrA =
398	        make_tensor(make_rmem_ptr(reinterpret_cast<A_type *>(pA)),
399	                    partition_shape_A(tiled_mma, Shape<Int<M>, Int<K>>{}));
400	    auto tCrB_view = make_tensor(tCrB.data(), remove_swizzle(tCrB.layout()));
401	    if constexpr (clear_accum) {
402	      clear(acc);
403	    }
404	    copy(tiled_copy_B, tCsB(_, _, 0), tCrB_copy_view(_, _, 0));
405	    CUTE_UNROLL
406	    for (int k = 0; k < size<2>(tCrA); ++k) {
407	      if (k < size<2>(tCrA) - 1) {
408	        copy(tiled_copy_B, tCsB(_, _, k + 1), tCrB_copy_view(_, _, k + 1));
409	      }
410	      gemm(tiled_mma, tCrA(_, _, k), tCrB_view(_, _, k), acc);
411	    }
412	  }
413	
414	  static CUTE_DEVICE void body_sr(A_type_raw *pA, B_type_raw *pB,
415	                                  C_type_raw *pC) {
416	    const int tid = threadIdx.x;
417	    Tensor sA_all = make_tensor(make_smem_ptr(reinterpret_cast<A_type *>(pA)),
418	                                SmemLayoutA{});
419	    Tensor sA = get_region_tensor<offset_a, M, K, !trans_A, lda>(sA_all);
420	    TileMma tiled_mma;
421	    auto thr_mma = tiled_mma.get_thread_slice(tid);
422	    auto tiled_copy_A = make_tiled_copy_A(SmemCopyA{}, tiled_mma);
423	    auto thr_copy_A = tiled_copy_A.get_thread_slice(tid);
424	
425	    Tensor tCrA = thr_mma.partition_fragment_A(sA);
426	    Tensor tCsA = thr_copy_A.partition_S(sA);
427	
428	    Tensor tCrA_copy_view = thr_copy_A.retile_D(tCrA);
429	
430	    Tensor acc =
431	        make_tensor(make_rmem_ptr(reinterpret_cast<C_type *>(pC)),
432	                    partition_shape_C(tiled_mma, Shape<Int<M>, Int<N>>{}));
433	    Tensor tCrB =
434	        make_tensor(make_rmem_ptr(reinterpret_cast<B_type *>(pB)),
435	                    partition_shape_B(tiled_mma, Shape<Int<N>, Int<K>>{}));
436	    auto tCrA_view = make_tensor(tCrA.data(), remove_swizzle(tCrA.layout()));
437	    if constexpr (clear_accum) {
438	      clear(acc);
439	    }
440	    copy(tiled_copy_A, tCsA(_, _, 0), tCrA_copy_view(_, _, 0));
441	    CUTE_UNROLL
442	    for (int k = 0; k < size<2>(tCrA); ++k) {
443	      if (k < size<2>(tCrA) - 1) {
444	        copy(tiled_copy_A, tCsA(_, _, k + 1), tCrA_copy_view(_, _, k + 1));
445	      }
446	      gemm(tiled_mma, tCrA_view(_, _, k), tCrB(_, _, k), acc);
447	    }
448	  }
449	};
