360	    cutlass::arch::NamedBarrier::arrive(
361	        NumMmaThreads, (1 - cutlass::canonical_warp_group_idx()) /*id*/);
362	  } else {
363	    cutlass::arch::NamedBarrier::arrive(
364	        NumMmaThreads,
365	        (cutlass::canonical_warp_group_idx() <= 1
366	             ? cutlass::canonical_warp_group_idx() + 1
367	             : cutlass::canonical_warp_group_idx() + 1 - 3) /*id*/);
368	    cutlass::arch::NamedBarrier::arrive(
369	        NumMmaThreads,
370	        (cutlass::canonical_warp_group_idx() <= 0
371	             ? cutlass::canonical_warp_group_idx() + 2
372	             : cutlass::canonical_warp_group_idx() + 2 - 3) /*id*/);
