379	    cutlass::arch::NamedBarrier::arrive(NumMmaThreads, 0);
380	  }
381	  if constexpr (NumMmaThreads == 384) {
382	    if (cutlass::canonical_warp_group_idx() > 1) {
383	      cutlass::arch::NamedBarrier::arrive(NumMmaThreads, 1 /*id*/);
