339	template <int M, int N, int K, int AtomM, int AtomN, int AtomK, bool trans_A,
340	          bool trans_B, typename A_type_raw, typename B_type_raw,
341	          typename C_type_raw>
342	class GemmTensorOp {
343	public:
344	  using A_type_cute = typename tl::to_cute_type<A_type_raw>::type;
345	  using B_type_cute = typename tl::to_cute_type<B_type_raw>::type;
346	  using A_type =
347	      typename std::conditional<std::is_same<A_type_cute, float>::value,
348	                                tfloat32_t, A_type_cute>::type;
349	  using B_type =
350	      typename std::conditional<std::is_same<B_type_cute, float>::value,
351	                                tfloat32_t, B_type_cute>::type;
352	  using C_type = C_type_raw;
353	
354	  static_assert(AtomM == 128 || AtomM == 64 || AtomM == 32);
355	
356	  static constexpr UMMA::Major UmmaMajorA =
357	      trans_A ? UMMA::Major::MN : UMMA::Major::K;
358	  static constexpr UMMA::Major UmmaMajorB =
359	      trans_B ? UMMA::Major::K : UMMA::Major::MN;
360	
361	  using SmemLayoutAtomA =
362	      decltype(sm100_smem_selector<UmmaMajorA, A_type, Int<M>, Int<K>>());
363	  using SmemLayoutAtomB =
364	      decltype(sm100_smem_selector<UmmaMajorB, B_type, Int<N>, Int<K>>());
365	
366	  using SmemLayoutA = decltype(tile_to_shape(
367	      SmemLayoutAtomA{}, Shape<Int<M>, Int<K>>{},
368	      conditional_t<trans_A, Step<_2, _1>, Step<_1, _2>>{}));
369	  using SmemLayoutB = decltype(tile_to_shape(
370	      SmemLayoutAtomB{}, Shape<Int<N>, Int<K>>{},
371	      conditional_t<trans_B, Step<_1, _2>, Step<_2, _1>>{}));
372	
373	  static CUTE_DEVICE void body_ss(A_type_raw *pA, B_type_raw *pB, uint32_t pC,
374	                                  uint64_t *umma_bar_ptr, bool clear_accum) {
375	    Tensor sA = make_tensor(make_smem_ptr(reinterpret_cast<A_type *>(pA)),
376	                            SmemLayoutA{});
377	    Tensor sB = make_tensor(make_smem_ptr(reinterpret_cast<B_type *>(pB)),
378	                            SmemLayoutB{});
379	
380	    // TODO (lei): Normal TCGEN5MMA (the one w/o ws) don't saturate all 128
381	    // lanes when M == 64
382	    // (see layout F in
383	    // https://docs.nvidia.com/cuda/parallel-thread-execution/#tcgen05-data-path-layout-f)
384	    // So we use the .ws variant here
385	    using MmaAtom =
386	        typename DispatchInstruction<A_type, B_type, C_type, AtomM, AtomN,
387	                                     AtomK, UmmaMajorA, UmmaMajorB>::MMA;
388	    auto tiled_mma = make_tiled_mma(MmaAtom{}, Layout<Shape<_1>>{},
389	                                    Tile<Int<M>, Int<N>, Int<K>>{});
390	    auto thr_mma = tiled_mma.get_slice(_0{});
391	    tiled_mma.accumulate_ =
392	        clear_accum ? UMMA::ScaleOut::Zero : UMMA::ScaleOut::One;
393	    Tensor acc = partition_fragment_C(tiled_mma, Shape<Int<M>, Int<N>>{});
394	    acc.data() = pC;
395	
396	    Tensor sA_frag = thr_mma.partition_fragment_A(sA);
397	    Tensor sB_frag = thr_mma.partition_fragment_B(sB);
398	    CUTLASS_PRAGMA_UNROLL
399	    for (int k_block = 0; k_block < size<2>(sA_frag); ++k_block) {
400	      cute::gemm(tiled_mma, sA_frag(_, _, k_block), sB_frag(_, _, k_block),
401	                 acc);
402	      tiled_mma.accumulate_ = UMMA::ScaleOut::One;
403	    }
404	
405	    cutlass::arch::umma_arrive(umma_bar_ptr);
406	  }
407	};
408	
409	} // namespace tl_tcgen5mma
410	
411	} // namespace cute
