427	          bool trans_B, typename C_type, typename A_type, typename B_type,
428	          typename Barrier_type>
429	TL_DEVICE void tcgen5mma_gemm_ss(A_type *pA, B_type *pB, uint32_t accum,
430	                                 Barrier_type *umma_bar_ptr, bool clear_accum) {
431	  using MMA =
