206	  constexpr int kLoopStride = 32 * UNROLL_FACTOR;
207	  typename std::remove_reference<decltype(LD_FUNC(src_addr + 0))>::type
208	      unrolled_values[UNROLL_FACTOR];
209	  auto __src = src_addr;
210	  auto __dst = dst_addr;
211	  for (int __i = lane_id; __i < (N / kLoopStride) * kLoopStride;
212	       __i += kLoopStride) {
213	    _Pragma("unroll") for (int __j = 0; __j < UNROLL_FACTOR; ++__j)
214	        unrolled_values[__j] = LD_FUNC(__src + __i + __j * 32);
215	    _Pragma("unroll") for (int __j = 0; __j < UNROLL_FACTOR; ++__j)
216	        ST_FUNC(__dst + __i + __j * 32, unrolled_values[__j]);
217	  }
218	  for (int __i = (N / kLoopStride) * kLoopStride + lane_id; __i < N; __i += 32)
219	    ST_FUNC(__dst + __i, LD_FUNC(__src + __i));
