277	template <int N, typename dtype_t>
278	TL_DEVICE void nvshmem_cp_threadgroup(dtype_t *__restrict__ _dst,
279	                                      const dtype_t *__restrict__ _src,
280	                                      int myIdx, int groupSize) {
281	  size_t len = N * sizeof(dtype_t);
282	  void *dst = _dst;
283	  const void *src = _src;
284	
285	  /*
286	   * If src and dst are 16B aligned copy as much as possible using 16B chunks
287	   */
288	  if ((uintptr_t)dst % 16 == 0 && (uintptr_t)src % 16 == 0) {
289	    const size_t nelems = len / 16;
290	
291	    int4 *__restrict__ dst_p = (int4 *)dst;
292	    const int4 *__restrict__ src_p = (const int4 *)src;
293	    for (size_t i = myIdx; i < nelems; i += groupSize)
294	      dst_p[i] = src_p[i];
295	
296	    len -= nelems * 16;
297	
298	    if (0 == len)
299	      return;
300	
301	    dst = (void *)(dst_p + nelems);
302	    src = (void *)(src_p + nelems);
303	  }
304	
305	  /*
306	   * If src and dst are 8B aligned copy as much as possible using 8B chunks
307	   */
308	  if ((uintptr_t)dst % 8 == 0 && (uintptr_t)src % 8 == 0) {
309	    uint64_t *__restrict__ dst_p = (uint64_t *)dst;
310	    const uint64_t *__restrict__ src_p = (const uint64_t *)src;
311	    const size_t nelems = len / 8;
312	
313	    for (size_t i = myIdx; i < nelems; i += groupSize)
314	      dst_p[i] = src_p[i];
315	
316	    len -= nelems * 8;
317	
318	    if (0 == len)
319	      return;
320	
321	    dst = (void *)(dst_p + nelems);
322	    src = (void *)(src_p + nelems);
323	  }
324	
325	  /*
326	   * If src and dst are 4B aligned copy as much as possible using 4B chunks
327	   */
328	  if ((uintptr_t)dst % 4 == 0 && (uintptr_t)src % 4 == 0) {
329	    uint32_t *__restrict__ dst_p = (uint32_t *)dst;
330	    const uint32_t *__restrict__ src_p = (const uint32_t *)src;
331	    const size_t nelems = len / 4;
332	
333	    for (size_t i = myIdx; i < nelems; i += groupSize)
334	      dst_p[i] = src_p[i];
335	
336	    len -= nelems * 4;
337	
338	    if (0 == len)
339	      return;
340	
341	    dst = (void *)(dst_p + nelems);
342	    src = (void *)(src_p + nelems);
343	  }
