346	   * If src and dst are 2B aligned copy as much as possible using 2B chunks
347	   */
348	  if ((uintptr_t)dst % 2 == 0 && (uintptr_t)src % 2 == 0) {
349	    uint16_t *__restrict__ dst_p = (uint16_t *)dst;
350	    const uint16_t *__restrict__ src_p = (const uint16_t *)src;
351	    const size_t nelems = len / 2;
352	
353	    for (size_t i = myIdx; i < nelems; i += groupSize)
354	      dst_p[i] = src_p[i];
